"import db from './src/lib/db';

async function test() {
  console.log('--- PREPARING TEST DATA ---');
  // Update 10 mock posts to have a 'created_at' of yesterday to test 'today' vs 'all' scope
  db.exec(`UPDATE posts SET created_at = datetime('now', '-1 day') WHERE is_mock = 1 AND id IN (SELECT id FROM posts WHERE is_mock = 1 LIMIT 10)`);
  console.log('Updated 10 mock posts to yesterday.');

  const PORT = 3000;

  console.log('\n--- GET /api/posts?scope=today&session_id=mock_session_id ---');
  const resToday = await fetch(`http://localhost:${PORT}/api/posts?scope=today&session_id=mock_session_id`);
  const dataToday = await resToday.json();
  console.log('Today count (should be 10):', dataToday.length);

  console.log('\n--- GET /api/posts?scope=all&session_id=mock_session_id ---');
  const resAll = await fetch(`http://localhost:${PORT}/api/posts?scope=all&session_id=mock_session_id`);
  const dataAll = await resAll.json();
  console.log('All count (should be 20):', dataAll.length);

  console.log('\n--- POST /api/posts/[id]/repost ---');
  if (dataAll.length > 0) {
    const parentId = dataAll[0].id; // taking the first post
    const repostRes = await fetch(`http://localhost:${PORT}/api/posts/${parentId}/repost`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ session_id: 'repost_tester', nickname: 'Tester' })
    });
    const repostData = await repostRes.json();
    console.log('Repost status:', repostRes.status);
    console.log('New repost ID:', repostData.id);

    console.log('\n--- VERIFY REPOST COUNT IN DB ---');
    const countRow = db.prepare('SELECT COUNT(*) as c FROM posts WHERE parent_id = ?').get(parentId) as any;
    console.log(`Original Post ID: ${parentId}`);
    console.log(`Child count in DB: ${countRow.c}`);
  }
}

test().catch(console.error);
"

"'use client';

export default function ScopeToggle({ scope, onChange }: { scope: 'today' | 'all', onChange: (scope: 'today' | 'all') => void }) {
  return (
    <div className="flex bg-gray-200 rounded-lg p-1 w-fit mb-4">
      <button 
        className={`px-4 py-2 rounded-md transition-colors ${scope === 'today' ? 'bg-white shadow text-gray-800' : 'text-gray-500 hover:bg-gray-300'}`}
        onClick={() => onChange('today')}
      >
        오늘
      </button>
      <button 
        className={`px-4 py-2 rounded-md transition-colors ${scope === 'all' ? 'bg-white shadow text-gray-800' : 'text-gray-500 hover:bg-gray-300'}`}
        onClick={() => onChange('all')}
      >
        전체
      </button>
    </div>
  );
}
"

"'use client';

export default function PostitCard({ post, onRepost }: { post: any, onRepost?: (id: string) => void }) {
  return (
    <div className={`p-4 rounded-xl shadow-md ${post.is_mock ? 'bg-yellow-50' : 'bg-orange-50'} mb-4 border border-yellow-200 relative`}>
      <p className="text-gray-800 mb-4">{post.content}</p>
      <div className="text-xs text-gray-500 flex justify-between items-center">
        <span>{post.nickname || '익명'}</span>
        <span>{new Date(post.created_at).toLocaleDateString()}</span>
      </div>
      {onRepost && (
        <button 
          onClick={() => onRepost(post.id)}
          className="absolute bottom-3 right-3 text-xs bg-white text-orange-500 border border-orange-200 px-3 py-1 rounded-full hover:bg-orange-50 transition-colors"
        >
          동참하기
        </button>
      )}
    </div>
  );
}
"

"'use client';

import { useState } from 'react';

export default function PostitForm({ onSubmit }: { onSubmit: (data: any) => void }) {
  const [content, setContent] = useState('');
  const [nickname, setNickname] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!content.trim()) return;

    let sessionId = localStorage.getItem('session_id');
    if (!sessionId) {
      sessionId = 'sess_' + Math.random().toString(36).substring(2, 11);
      localStorage.setItem('session_id', sessionId);
    }

    onSubmit({ content, nickname, session_id: sessionId });
    setContent('');
    setNickname('');
  };

  return (
    <form onSubmit={handleSubmit} className="mb-8 p-4 bg-white rounded-xl shadow-sm border border-gray-100">
      <textarea
        className="w-full p-3 border border-gray-200 rounded-lg mb-3 text-gray-800 focus:outline-none focus:ring-2 focus:ring-orange-200 resize-none"
        rows={3}
        placeholder="당신의 작은 선행을 공유해주세요..."
        value={content}
        onChange={(e) => setContent(e.target.value)}
        required
      />
      <div className="flex gap-2">
        <input 
          type="text"
          className="flex-1 border border-gray-200 p-2 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-orange-200 text-gray-800"
          placeholder="닉네임 (선택)"
          value={nickname}
          onChange={(e) => setNickname(e.target.value)}
        />
        <button type="submit" className="bg-orange-500 text-white px-5 py-2 rounded-lg font-medium hover:bg-orange-600 transition-colors whitespace-nowrap">
          붙이기
        </button>
      </div>
    </form>
  );
}
"

