"const puppeteer = require('puppeteer');

(async () => {
  const browser = await puppeteer.launch({ headless: 'new' });
  const page = await browser.newPage();

  console.log('Navigating to http://localhost:3000/...');
  await page.goto('http://localhost:3000/', { waitUntil: 'networkidle2' });

  console.log('=== Campaign 2x Effect UI Test ===');

  // Type target keyword in textarea
  await page.type('textarea', '오늘 이웃에게 먼저 인사 했어요!');

  // Submit the form
  await page.click('button[type="submit"]');

  // Wait a little for UI effect
  await new Promise(r => setTimeout(r, 500));

  // Check if the "✨ 따뜻함이 2배로 적립되었습니다! ✨" element appears
  const effectText = await page.evaluate(() => {
    const el = document.querySelector('.text-orange-500.font-bold');
    return el ? el.innerText : null;
  });

  if (effectText && effectText.includes('2배')) {
    console.log('=> SUCCESS: Campaign 2x effect text rendered in DOM!');
  } else {
    console.log('=> FAILURE: Effect not found in DOM.');
  }

  await browser.close();
})();
"

