  // 1. Get the least used category over the last 7 days
  try {
    const rows = db.prepare(`
      SELECT category, COUNT(*) as count 
      FROM posts 
      WHERE created_at >= date('now', '-7 days')
        AND category IS NOT NULL
      GROUP BY category
      ORDER BY count ASC
    `).all() as {category: string, count: number}[];

    // Default categories if DB is empty
    const allCategories = ['도움', '배려', '인사', '나눔', '환경', '기타'];
    let targetCategory = '인사'; // fallback

    // If there are used categories, find those that are NOT in the list (count = 0)
    // or pick the absolute lowest.
    const usedCategories = rows.map(r => r.category);
    const unusedCategories = allCategories.filter(c => !usedCategories.includes(c));

    if (unusedCategories.length > 0) {
      // Pick a random unused category
      targetCategory = unusedCategories[Math.floor(Math.random() * unusedCategories.length)];
    } else if (rows.length > 0) {
      // Pick the least used
      targetCategory = rows[0].category;
    }

    // 2. We skip calling Gemini API here for simplicity and speed in Hackathon, 
