"const Database = require('better-sqlite3');
const bcrypt = require('bcryptjs');
const crypto = require('crypto');

const db = new Database('./data/warmth_wall.db');

const email = 'dasom@test.com';
const password = '12345678';

// Check if user exists
const existing = db.prepare('SELECT * FROM users WHERE email = ?').get(email);
if (existing) {
  // Update password
  const hash = bcrypt.hashSync(password, 10);
  db.prepare('UPDATE users SET password_hash = ? WHERE email = ?').run(hash, email);
  console.log('Updated password for', email, '-> user_id:', existing.id);
} else {
  // Create new user
  const id = crypto.randomUUID();
  const hash = bcrypt.hashSync(password, 10);
  db.prepare('INSERT INTO users (id, email, password_hash) VALUES (?, ?, ?)').run(id, email, hash);
  console.log('Created user', email, '-> user_id:', id);
}

db.close();
"

